<?php
namespace Dth\Crm\Filament\Resources\LeadResource\RelationManagers; use Filament\Resources\RelationManagers\RelationManager; use Filament\Schemas\Schema; use Filament\Tables\Table; use Filament\Tables\Columns\TextColumn; use Filament\Actions; use Filament\Forms\Components\{Select,TextInput,Textarea,DateTimePicker};
class ActivitiesRelationManager extends RelationManager {protected static string $relationship='activities';public static function getTitle($o,string $p):string{return 'Lịch sử hoạt động';} public function form(Schema $s):Schema{return $s->components([Select::make('type')->options(\Dth\Crm\Enums\LeadActivityType::options())->required(),TextInput::make('subject')->label('Chủ đề'),Textarea::make('content')->label('Nội dung')->rows(3),TextInput::make('outcome')->label('Kết quả'),DateTimePicker::make('activity_at')->default(now())->required(),DateTimePicker::make('next_follow_up_at')->label('Theo dõi tiếp')]);} public function table(Table $t):Table{return $t->columns([TextColumn::make('type')->badge(),TextColumn::make('subject'),TextColumn::make('outcome'),TextColumn::make('activity_at')->dateTime('d/m/Y H:i'),TextColumn::make('next_follow_up_at')->dateTime('d/m/Y H:i')])->headerActions([Actions\CreateAction::make()->mutateDataUsing(fn($d)=>$d+['staff_id'=>\Dth\Crm\Models\Staff::where('user_id',auth()->id())->value('id')])])->recordActions([Actions\EditAction::make(),Actions\DeleteAction::make()]);}}
